mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, sys, time, urllib.request, urllib.error
BASE = "http://localhost:8080"
token = None
def get_token():
    global token
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        token = json.load(r)["token"]
def call(path, auth=True):
    attempt = 0
    while True:
        attempt += 1
        if auth and token is None:
            get_token()
        headers = {"Authorization": "Bearer " + token} if auth else {}
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, json.load(r)
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            if e.code == 404:
                return 404, None
            print(f"HTTP {e.code} {path} attempt {attempt}: {body[:200]} headers={dict(e.headers)}", file=sys.stderr)
            if e.code == 401:
                get_token(); continue
            if e.code == 429 or e.code == 503:
                wait = e.headers.get("Retry-After")
                if wait is None:
                    try: wait = json.loads(body).get("retry_after", 1)
                    except Exception: wait = 1
                time.sleep(float(wait)); continue
            time.sleep(min(2 ** attempt, 30)); continue
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            print(f"net error {path} attempt {attempt}: {e}", file=sys.stderr)
            time.sleep(min(2 ** attempt, 30)); continue
EOF
cat > /tmp/recon/probe.py <<'EOF'
import sys; sys.path.insert(0, "/tmp/recon")
from fetch import call
import json
pages = {}
p = 1
while True:
    s, d = call(f"/orders?page={p}")
    pages[p] = d
    print("page", p, "items", len(d["items"]), "next", d["next"], "total", d["total_pages"], flush=True)
    if d["next"] is None: break
    p += 1
json.dump(pages, open("/tmp/recon/pages.json", "w"))
EOF
cd /tmp/recon && timeout 550 python3 -I probe.py 2>&1 | tail -60

